function generateCover(title: string, color: string): string {
  let hash = 0;
  for (let i = 0; i < title.length; i++) {
    hash = (hash * 31 + title.charCodeAt(i)) | 0;
  }
  return `https://picsum.photos/seed/${Math.abs(hash)}/400/600`;
}

