function seededRandom(seed: number): number {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

function generateDemoBook(
  id: number,
  subcategoryName: string,
  subcategorySlug: string,
  categorySlug: string,
  index: number
): DemoBook {
  const cat = categories.find((c) => c.slug === categorySlug)!;
  const seed = id * 100 + index;
  const r = (offset: number) => seededRandom(seed + offset);

  const title = subcategoryName + " Guide " + (index + 1);
  const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/-+$/, "");
  const author = authors[id % authors.length];
  const price = Math.round((5.99 + r(1) * 19) * 100) / 100;
  const hasDiscount = r(2) > 0.6;
  const coverIndex = id % coverColors.length;

  return {
    id: "b" + id,
    title,
    slug,
    author,
    category: cat,
    subcategory: subcategoryName,
    price,
    discountPrice: hasDiscount ? Math.round(price * 0.7 * 100) / 100 : null,
    coverImage: generateCover(title, coverColors[coverIndex]),
    averageRating: Math.round((3.5 + r(3) * 1.5) * 10) / 10,
    totalReviews: Math.floor(10 + r(4) * 290),
    totalSales: Math.floor(100 + r(5) * 4900),
    description: "A comprehensive guide to " + subcategoryName.toLowerCase() + ". This book covers essential concepts, practical strategies, and expert insights for mastering " + subcategoryName.toLowerCase() + ".",
    format: "EBOOK",
    isbn: "978-1-23456" + String(id).padStart(3, "0") + "-" + Math.floor(r(6) * 10),
    pageCount: Math.floor(150 + r(7) * 300),
    language: "English",
    publicationDate: "2024-" + String(1 + Math.floor(r(8) * 12)).padStart(2, "0") + "-" + String(1 + Math.floor(r(9) * 28)).padStart(2, "0"),
    publisher: "Statement Publications",
    tags: [subcategorySlug, categorySlug],
    isNew: r(10) > 0.5,
    isBestseller: r(11) < 0.1,
    isFeatured: r(12) < 0.15,
    isPreOrder: false,
    isAudiobook: r(13) < 0.3,
    collection: null,
  };
}

const existingBooks: DemoBook[] = rawBooks;

const generatedBooks: DemoBook[] = [];
let nextBookId = 101;

for (const group of categoryGroups) {
  for (const sub of group.subcategories) {
    for (let i = 0; i < 10; i++) {
      generatedBooks.push(
        generateDemoBook(nextBookId, sub.name, sub.slug, group.slug, i)
      );
      nextBookId++;
    }
  }
}

export const books: DemoBook[] = [...existingBooks, ...generatedBooks];
export const allBooks: DemoBook[] = books;


