export function getBooksByCategory(categorySlug: string): DemoBook[] {
  return allBooks.filter((b) => b.category.slug === categorySlug);
}

export function getBooksByAuthor(authorSlug: string): DemoBook[] {
  return allBooks.filter((b) => b.author.slug === authorSlug);
}

export function getBookBySlug(slug: string): DemoBook | undefined {
  return allBooks.find((b) => b.slug === slug);
}

export function getAuthorBySlug(slug: string): DemoAuthor | undefined {
  return authors.find((a) => a.slug === slug);
}

export function getCategoryBySlug(slug: string): DemoCategory | undefined {
  return categories.find((c) => c.slug === slug);
}

export function getFeaturedBooks(): DemoBook[] {
  return allBooks.filter((b) => b.isFeatured);
}

export function getBestsellerBooks(): DemoBook[] {
  return allBooks.filter((b) => b.isBestseller);
}

export function getNewReleases(): DemoBook[] {
  return allBooks.filter((b) => b.isNew);
}

export function searchBooks(query: string): DemoBook[] {
  const q = query.toLowerCase();
  return allBooks.filter(
    (b) =>
      b.title.toLowerCase().includes(q) ||
      b.author.name.toLowerCase().includes(q) ||
      b.category.name.toLowerCase().includes(q) ||
      b.tags.some((t) => t.toLowerCase().includes(q))
  );
}

export function getPreOrderBooks(): DemoBook[] {
  return allBooks.filter((b) => b.isPreOrder);
}

export function getDealsBooks(): DemoBook[] {
  return allBooks.filter((b) => b.discountPrice !== null);
}

export function getAudiobooks(): DemoAudiobook[] {
  return audiobooks;
}

export function getBooksByCollection(collection: string): DemoBook[] {
  return allBooks.filter((b) => b.collection === collection);
}

export function getBlogPosts(): BlogPost[] {
  return blogPosts;
}

export function getFAQs(): FAQItem[] {
  return faqItems;
}
